/*
 * Optimized character classification using SIMD when possible.
 * Returns 1 if the fast path was taken, 0 otherwise.
 */
static int
_vec_string_fast_isalpha(PyArrayObject* char_array,
                         PyArray_Descr* type, PyObject* method,
                         PyArrayObject** result_out)
{
    /* Only optimize for Unicode string arrays with known methods */
    if (PyArray_TYPE(char_array) != NPY_UNICODE) {
        return 0;
    }

    /* Only optimize for no-argument character classification methods */
    const char* method_name = PyUnicode_AsUTF8(method);
    if (method_name == NULL) {
        return 0;
    }

    static const char* fast_methods[] = {
        "isalpha", "isdigit", "isalnum", "isupper", "islower", "isspace", NULL
    };

    int found = 0;
    for (int i = 0; fast_methods[i] != NULL; i++) {
        if (strcmp(method_name, fast_methods[i]) == 0) {
            found = 1;
            break;
        }
    }
    if (!found) {
        return 0;
    }

    /* Get array info */
    PyArrayIterObject *in_iter = NULL;
    PyArrayIterObject *out_iter = NULL;
    PyArrayObject *result = NULL;

    /* Get character size (4 bytes for Unicode) */
    const int char_size = 4;
    int itemsize = PyArray_ITEMSIZE(char_array) / char_size;

    in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
    if (in_iter == NULL) {
        goto fail;
    }

    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto fail;
    }

    out_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)result);
    if (out_iter == NULL) {
        goto fail;
    }

    /* Get method to call for non-SIMD fallback and zero-length strings */
    PyObject *method_func = PyObject_GetAttr((PyObject *)&PyUnicode_Type, method);
    if (method_func == NULL) {
        goto fail;
    }

    /* Process strings */
    while (PyArray_ITER_NOTDONE(in_iter)) {
        PyObject *item_result;
        PyObject *item;
        npy_uint8 *in_data;
        npy_bool *out_data;
        int string_len;
        int i;
        int is_all_alpha;

        item = PyArray_ToScalar(in_iter->dataptr, in_iter->ao);
        if (item == NULL) {
            Py_DECREF(method_func);
            goto fail;
        }

        /* Get string length */
        string_len = PyUnicode_GetLength(item);
        if (string_len < 0) {
            Py_DECREF(item);
            Py_DECREF(method_func);
            goto fail;
        }

        /* For zero-length strings, use Python fallback */
        if (string_len == 0) {
            item_result = PyObject_CallFunctionObjArgs(method_func, item, NULL);
            Py_DECREF(item);
            if (item_result == NULL) {
                Py_DECREF(method_func);
                goto fail;
            }
            if (PyArray_SETITEM(result, PyArray_ITER_DATA(out_iter), item_result)) {
                Py_DECREF(item_result);
                Py_DECREF(method_func);
                PyErr_SetString(PyExc_TypeError,
                        "result array type does not match underlying function");
                goto fail;
            }
            Py_DECREF(item_result);
            PyArray_MultiIter_NEXT(in_iter);
            PyArray_ITER_NEXT(out_iter);
            continue;
        }

        /* Get raw data pointer - Unicode strings are stored as 4-byte characters */
        in_data = (npy_uint8 *)in_iter->dataptr;
        out_data = (npy_bool *)out_iter->dataptr;

        /* Check if data is properly aligned for SIMD */
        if (((npy_uintptr)in_data % 32) != 0) {
            /* Fall back to Python for unaligned data */
            item_result = PyObject_CallFunctionObjArgs(method_func, item, NULL);
            Py_DECREF(item);
            if (item_result == NULL) {
                Py_DECREF(method_func);
                goto fail;
            }
            if (PyArray_SETITEM(result, PyArray_ITER_DATA(out_iter), item_result)) {
                Py_DECREF(item_result);
                Py_DECREF(method_func);
                PyErr_SetString(PyExc_TypeError,
                        "result array type does not match underlying function");
                goto fail;
            }
            Py_DECREF(item_result);
            PyArray_MultiIter_NEXT(in_iter);
            PyArray_ITER_NEXT(out_iter);
            continue;
        }

        /* For isalpha: check if all characters are alphabetic.
         * Alpha chars: 'A'-'Z' or 'a'-'z' (ASCII only for now)
         * We process 32 bytes at a time using AVX2
         */
        is_all_alpha = 1;
#if defined(NPY_HAVE_AVX2)
        if (strcmp(method_name, "isalpha") == 0 && string_len >= 32) {
            __m256i mask_lo = _mm256_set1_epi8(0xDF);  /* To uppercase: clear bit 0x20 */
            __m256i mask_hi = _mm256_set1_epi8(0x40);  /* 'A' - 1 */
            __m256i mask_lo2 = _mm256_set1_epi8(0x19); /* 'Z' - 'A' */

            int simd_len = (string_len / 32) * 32;

            for (i = 0; i < simd_len; i += 32) {
                __m256i data = _mm256_load_si256((const __m256i*)(in_data + i * 4));
                __m256i upper = _mm256_and_si256(data, mask_lo);
                __m256i above_a = _mm256_cmpgt_epi8(upper, mask_hi);
                __m256i below_z = _mm256_cmpgt_epi8(mask_lo2, upper);
                __m256i is_alpha_range = _mm256_andnot_si256(below_z, above_a);

                /* Also check for non-ASCII (any byte with high bit set is not ASCII alpha) */
                __m256i high_bit = _mm256_cmpgt_epi8(data, _mm256_set1_epi8(127));
                is_alpha_range = _mm256_andnot_si256(high_bit, is_alpha_range);

                /* If any lane is false (0), the string is not all alpha */
                __m256i zero = _mm256_setzero_si256();
                __m256i test = _mm256_cmpeq_epi8(is_alpha_range, zero);
                int mask = _mm256_movemask_epi8(test);
                if (mask != 0) {
                    is_all_alpha = 0;
                    break;
                }
            }

            /* Handle remainder */
            for (; i < string_len; i++) {
                npy_uint32 ch = *(npy_uint32*)(in_data + i * 4);
                if (ch > 127) {
                    is_all_alpha = 0;
                    break;
                }
                if (!((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z'))) {
                    is_all_alpha = 0;
                    break;
                }
            }
        }
        else if (strcmp(method_name, "isdigit") == 0 && string_len >= 32) {
            /* For isdigit: check if all characters are digits '0'-'9' */
            __m256i mask_lo = _mm256_set1_epi8('0' - 1);
            __m256i mask_hi = _mm256_set1_epi8('9');

            int simd_len = (string_len / 32) * 32;

            for (i = 0; i < simd_len; i += 32) {
                __m256i data = _mm256_load_si256((const __m256i*)(in_data + i * 4));
                __m256i above_zero = _mm256_cmpgt_epi8(data, mask_lo);
                __m256i below_nine = _mm256_cmpgt_epi8(mask_hi, data);
                __m256i is_digit_range = _mm256_andnot_si256(below_nine, above_zero);

                /* Also check for non-ASCII */
                __m256i high_bit = _mm256_cmpgt_epi8(data, _mm256_set1_epi8(127));
                is_digit_range = _mm256_andnot_si256(high_bit, is_digit_range);

                __m256i zero = _mm256_setzero_si256();
                __m256i test = _mm256_cmpeq_epi8(is_digit_range, zero);
                int mask = _mm256_movemask_epi8(test);
                if (mask != 0) {
                    is_all_alpha = 0;
                    break;
                }
            }

            /* Handle remainder */
            for (; i < string_len; i++) {
                npy_uint32 ch = *(npy_uint32*)(in_data + i * 4);
                if (ch > 127) {
                    is_all_alpha = 0;
                    break;
                }
                if (ch < '0' || ch > '9') {
                    is_all_alpha = 0;
                    break;
                }
            }
        }
        else
#endif
        {
            /* Fall back to Python for this method/length combination */
            item_result = PyObject_CallFunctionObjArgs(method_func, item, NULL);
            Py_DECREF(item);
            if (item_result == NULL) {
                Py_DECREF(method_func);
                goto fail;
            }
            if (PyArray_SETITEM(result, PyArray_ITER_DATA(out_iter), item_result)) {
                Py_DECREF(item_result);
                Py_DECREF(method_func);
                PyErr_SetString(PyExc_TypeError,
                        "result array type does not match underlying function");
                goto fail;
            }
            Py_DECREF(item_result);
            PyArray_MultiIter_NEXT(in_iter);
            PyArray_ITER_NEXT(out_iter);
            Py_DECREF(method_func);
            continue;
        }

        Py_DECREF(item);
        Py_DECREF(method_func);

        *out_data = is_all_alpha;

        PyArray_MultiIter_NEXT(in_iter);
        PyArray_ITER_NEXT(out_iter);
    }

    Py_DECREF(in_iter);
    Py_DECREF(out_iter);
    *result_out = result;
    return 1;

fail:
    Py_XDECREF(in_iter);
    Py_XDECREF(out_iter);
    Py_XDECREF(result);
    return 0;
}

