/*
 * Optimized character classification using SIMD when possible.
 * Returns 1 if the fast path was taken, 0 otherwise.
 * For isalpha: check if all characters are alphabetic.
 * Alpha chars: 'A'-'Z' or 'a'-'z' (ASCII only for now)
 * For isdigit: check if all characters are digits '0'-'9'
 */
static int
_vec_string_fast_char_check(PyArrayObject* char_array,
                             PyArray_Descr* type, PyObject* method,
                             PyArrayObject** result_out)
{
    PyArrayIterObject *in_iter = NULL;
    PyArrayIterObject *out_iter = NULL;
    PyArrayObject *result = NULL;
    PyObject *method_func = NULL;
    const char* method_name = NULL;

    /* Only optimize for Unicode string arrays */
    if (PyArray_TYPE(char_array) != NPY_UNICODE) {
        return 0;
    }

    /* Get method name */
    method_name = PyUnicode_AsUTF8(method);
    if (method_name == NULL) {
        return 0;
    }

    /* Only optimize for specific character classification methods */
    if (strcmp(method_name, "isalpha") != 0 &&
        strcmp(method_name, "isdigit") != 0) {
        return 0;
    }

    /* Get the Python method for fallback */
    method_func = PyObject_GetAttr((PyObject *)&PyUnicode_Type, method);
    if (method_func == NULL) {
        return 0;
    }

    in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
    if (in_iter == NULL) {
        goto fail;
    }

    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto fail;
    }

    out_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)result);
    if (out_iter == NULL) {
        goto fail;
    }

    /* Process strings */
    while (PyArray_ITER_NOTDONE(in_iter)) {
        PyObject *item_result = NULL;
        PyObject *item = NULL;
        int string_len;
        int i;
        int is_valid = 1;
        npy_uint8 *in_data;
        npy_bool *out_data;

        item = PyArray_ToScalar(in_iter->dataptr, in_iter->ao);
        if (item == NULL) {
            goto fail;
        }

        /* Get string length */
        string_len = PyUnicode_GetLength(item);
        if (string_len < 0) {
            Py_DECREF(item);
            goto fail;
        }

