        in_data = (npy_uint8 *)in_iter->dataptr;
        out_data = (npy_bool *)out_iter->dataptr;

#if defined(NPY_HAVE_AVX2)
        /* Try SIMD path for isalpha */
        if (strcmp(method_name, "isalpha") == 0 && string_len >= 16) {
            __m256i mask_hi = _mm256_set1_epi8('Z');
