/*
 * Fast character classification using C loops instead of Python calls.
 * This optimization applies to isalpha and isdigit for Unicode string arrays.
 * Returns 1 if the fast path was taken, 0 otherwise.
 */
static int
_vec_string_fast_char_check(PyArrayObject* char_array,
                             PyArray_Descr* type, PyObject* method,
                             PyArrayObject** result_out)
{
    PyArrayIterObject *in_iter = NULL;
    PyArrayIterObject *out_iter = NULL;
    PyArrayObject *result = NULL;
    const char* method_name = NULL;
    int is_isalpha = 0;
    int is_isdigit = 0;

    /* Only optimize for Unicode string arrays */
    if (PyArray_TYPE(char_array) != NPY_UNICODE) {
        return 0;
    }

    /* Get method name */
    method_name = PyUnicode_AsUTF8(method);
    if (method_name == NULL) {
        return 0;
    }

    /* Only optimize for specific character classification methods */
    if (strcmp(method_name, "isalpha") == 0) {
        is_isalpha = 1;
    }
    else if (strcmp(method_name, "isdigit") == 0) {
        is_isdigit = 1;
    }
    else {
        return 0;
    }

    in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
    if (in_iter == NULL) {
        return 0;
    }

    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        Py_DECREF(in_iter);
        return 0;
    }

    out_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)result);
    if (out_iter == NULL) {
        Py_DECREF(in_iter);
        Py_DECREF(result);
        return 0;
    }

    /* Process strings */
    while (PyArray_ITER_NOTDONE(in_iter)) {
        PyObject *item = NULL;
        int string_len;
        int i;
        int is_valid = 1;
        npy_uint8 *in_data;
        npy_bool *out_data;

        item = PyArray_ToScalar(in_iter->dataptr, in_iter->ao);
        if (item == NULL) {
            goto fail;
        }

        /* Get string length */
        string_len = PyUnicode_GetLength(item);
        Py_DECREF(item);
        if (string_len < 0) {
            goto fail;
        }

        /* Get raw data pointer - Unicode strings are stored as 4-byte characters */
        in_data = (npy_uint8 *)in_iter->dataptr;
        out_data = (npy_bool *)out_iter->dataptr;

        /* Process characters in C - much faster than calling Python for each char */
        if (is_isalpha) {
            for (i = 0; i < string_len; i++) {
                npy_uint32 ch = *(npy_uint32*)(in_data + i * 4);
                /* Non-ASCII is not ASCII alpha */
                if (ch > 127) {
                    is_valid = 0;
                    break;
                }
                /* Check for A-Z or a-z */
                if (!((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z'))) {
                    is_valid = 0;
                    break;
                }
            }
        }
        else if (is_isdigit) {
            for (i = 0; i < string_len; i++) {
                npy_uint32 ch = *(npy_uint32*)(in_data + i * 4);
                /* Non-ASCII is not ASCII digit */
                if (ch > 127) {
                    is_valid = 0;
                    break;
                }
                /* Check for 0-9 */
                if (ch < '0' || ch > '9') {
                    is_valid = 0;
                    break;
                }
            }
        }

        /* Set the result directly */
        *out_data = is_valid ? 1 : 0;

        PyArray_ITER_NEXT(in_iter);
        PyArray_ITER_NEXT(out_iter);
    }

    Py_DECREF(in_iter);
    Py_DECREF(out_iter);
    *result_out = result;
    return 1;

fail:
    Py_XDECREF(in_iter);
    Py_XDECREF(out_iter);
    Py_XDECREF(result);
    return 0;
}

